html:
{%- set company_doc = frappe.get_doc('Company', doc.company) if doc.get('company') else None -%}
{%- macro vnd(amount) -%}{{ '{:,.0f}'.format(amount or 0).replace(',', '.') }}{%- endmacro -%}
{%- set d = frappe.utils.getdate(doc.posting_date) -%}
{%- set is_tscd = doc.scope == 'TSCĐ' -%}

<style>
@media print {
  @page { size: A4 portrait; margin: 20mm 15mm; }
  .ah-print table thead { display: table-header-group; }
  .ah-print table tfoot { display: table-footer-group; }
  .ah-print table tbody tr { page-break-inside: avoid; }
  .ah-print .signatures { page-break-inside: avoid; }
}
.ah-print a { color: inherit !important; text-decoration: none !important; }
.ah-print { font-family: 'Times New Roman', Times, serif; font-size: 13px; line-height: 1.6; max-width: 700px; margin: 0 auto; }
.ah-print .header-national { text-align: center; font-weight: bold; text-transform: uppercase; margin-bottom: 5px; }
.ah-print .header-motto { text-align: center; font-style: italic; margin-bottom: 20px; }
.ah-print h2 { text-align: center; font-size: 16px; font-weight: bold; text-transform: uppercase; margin: 15px 0 5px 0; }
.ah-print .sub-title { text-align: center; font-style: italic; margin-bottom: 15px; }
.ah-print table { width: 100%; border-collapse: collapse; margin: 10px 0; }
.ah-print table th, .ah-print table td { border: 1px solid #333; padding: 4px 8px; font-size: 12px; }
.ah-print table th { background: #f0f0f0; text-align: center; font-weight: bold; }
.ah-print .info-row { margin: 6px 0; }
.ah-print .signatures { display: flex; justify-content: space-around; margin-top: 30px; text-align: center; }
.ah-print .sign-block { width: 28%; }
.ah-print .sign-block .sign-title { font-weight: bold; }
.ah-print .sign-block .sign-date { font-style: italic; font-size: 11px; }
.ah-print .sign-block .sign-space { height: 50px; }
.ah-print .total-row { font-weight: bold; }
</style>

<div class='ah-print'>
  <div class='header-national'>Cộng hòa xã hội chủ nghĩa Việt Nam</div>
  <div class='header-motto'>Độc lập - Tự do - Hạnh phúc</div>

  <h2>{{ 'BIÊN BẢN GIAO NHẬN TÀI SẢN CỐ ĐỊNH' if is_tscd else 'BIÊN BẢN GIAO NHẬN CCDC' }}</h2>
  <div class='sub-title'>Mẫu S22-DN (TT99/2025/TT-BTC)</div>

  <div class='info-row'><b>Số phiếu:</b> {{ doc.name }}</div>
  <div class='info-row'><b>Ngày:</b> Ngày {{ d.day }} tháng {{ d.month }} năm {{ d.year }}</div>
  {%- if company_doc %}
  <div class='info-row'><b>Đơn vị:</b> {{ company_doc.company_name }}</div>
  {%- endif %}
  <div class='info-row'><b>Lý do giao nhận:</b> {{ doc.reason or '' }}</div>

  <div class='info-row' style='margin-top:10px'>
    <b>Bên giao:</b> {{ doc.from_employee or '' }} — Phòng: {{ doc.from_department or '' }}
  </div>
  <div class='info-row'>
    <b>Bên nhận:</b> {{ doc.to_employee or '' }} — Phòng: {{ doc.to_department or '' }} — Địa điểm: {{ doc.to_location or '' }}
  </div>
  {%- if doc.co_signer_employee %}
  <div class='info-row'><b>Người chứng kiến:</b> {{ doc.co_signer_employee }}</div>
  {%- endif %}

  <table style='margin-top:15px'>
    <thead>
      <tr>
        <th style='width:5%'>STT</th>
        <th style='width:35%'>Tên {{ 'tài sản' if is_tscd else 'CCDC' }}</th>
        <th style='width:15%'>Số hiệu/Serial</th>
        <th style='width:20%'>Giá trị sổ sách (VNĐ)</th>
        <th style='width:25%'>Ghi chú</th>
      </tr>
    </thead>
    <tbody>
      {%- for item in doc.handover_items or [] %}
      <tr>
        <td style='text-align:center'>{{ loop.index }}</td>
        <td>{{ item.asset_name or item.target_name }}</td>
        <td style='text-align:center'>{{ item.serial_no or '' }}</td>
        <td style='text-align:right'>{{ vnd(item.book_value) }}</td>
        <td>{{ item.remarks or '' }}</td>
      </tr>
      {%- endfor %}
      <tr class='total-row'>
        <td colspan='3' style='text-align:right'>Tổng cộng</td>
        <td style='text-align:right'>{{ vnd(doc.total_asset_value) }}</td>
        <td></td>
      </tr>
    </tbody>
  </table>

  {%- if doc.remarks %}
  <div class='info-row' style='margin-top:10px'><b>Ghi chú:</b> {{ doc.remarks }}</div>
  {%- endif %}

  <div class='signatures'>
    <div class='sign-block'>
      <div class='sign-title'>Bên giao</div>
      <div class='sign-date'>(Ký, họ tên)</div>
      <div class='sign-space'></div>
      <div>{{ doc.from_employee or '' }}</div>
    </div>
    <div class='sign-block'>
      <div class='sign-title'>Bên nhận</div>
      <div class='sign-date'>(Ký, họ tên)</div>
      <div class='sign-space'></div>
      <div>{{ doc.to_employee or '' }}</div>
    </div>
    {%- if doc.co_signer_employee %}
    <div class='sign-block'>
      <div class='sign-title'>Người chứng kiến</div>
      <div class='sign-date'>(Ký, họ tên)</div>
      <div class='sign-space'></div>
      <div>{{ doc.co_signer_employee }}</div>
    </div>
    {%- else %}
    <div class='sign-block'>
      <div class='sign-title'>Kế toán</div>
      <div class='sign-date'>(Ký, họ tên)</div>
      <div class='sign-space'></div>
    </div>
    {%- endif %}
  </div>
</div>
<div style='text-align:center; margin-top:20px; font-size:10pt; color:#555;'>(Mẫu S22-DN theo Thông tư 99/2025/TT-BTC ngày 31/12/2025)</div>
